$(function(){
  $(".c-sidebar-toggle").on("click", function(e){
    e.preventDefault();
    e.stopPropagation();
    $(".js-page-sidebar").toggleClass("is-visible");
    $(".o-page").toggleClass("is-sidebar-collapsed");
  });
  $(document).on("click", function(e){
    if (!$(e.target).closest(".js-page-sidebar, .c-sidebar-toggle").length) {
      $(".js-page-sidebar").removeClass("is-visible");
    }
  });
});
